  [/\b(a|an|the)\b/,()=>a==='an'?'نستخدم an قبل الكلمة التي تبدأ بصوت متحرك، مثل an apple.':a==='a'?'نستخدم a قبل الاسم المفرد المعدود الذي يبدأ بصوت ساكن، مثل a book.':'نستخدم the عندما نشير إلى اسم محدد أو معروف.'],
  [/\b(he|she|it|they|we|you|i)\b/,()=>['he','she','it','they','we','you','i'].includes(a)?'اختر الضمير بحسب المعنى: he للمذكر، she للمؤنث، it لغير العاقل، they للجمع.':'طابق الفعل مع الفاعل، وفي المضارع البسيط نضيف s أو es مع he/she/it.'],
  [/\b(this|that|these|those)\b/,()=> 'This وThat للمفرد، وThese وThose للجمع؛ This وThese للقريب.'],
  [/\b(do|does|did|don.t|doesn.t)\b/,()=> 'نستخدم do مع I/you/we/they وdoes مع he/she/it، وdid للماضي. بعد الفعل المساعد يأتي الفعل في صورته الأساسية.'],
  [/\b(have|has|had)\b/,()=> 'نستخدم have مع I/you/we/they، وhas مع he/she/it، وhad للماضي.'],
